import{_ as e,o as r,c as a,ag as s}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Paper Presentations","description":"","frontmatter":{"source":"graduate/paper-presentations.md"},"headers":[],"relativePath":"graduate/paper-presentations.md","filePath":"graduate/paper-presentations.md"}'),o={name:"graduate/paper-presentations.md"};function n(i,t,d,h,l,u){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="paper-presentations" tabindex="-1">Paper Presentations <a class="header-anchor" href="#paper-presentations" aria-label="Permalink to &quot;Paper Presentations&quot;">​</a></h1><blockquote><p>Each CS [5xxx] student presents one research paper to the class and serves once as discussant for a classmate&#39;s. Undergraduates take part too, with one question each. The goal is to read research the way an engineer has to now: what does it show, how strong is that, and what should change in practice?</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Who</strong></td><td>Every CS [5xxx] student: one presentation and one discussant role. Every other student posts one question beforehand</td></tr><tr><td><strong>When</strong></td><td>One presentation per Seminar, weeks 3–14. That Seminar&#39;s concept talk shrinks to 18 minutes, and the presentation and discussion take the reading-discussion block and more</td></tr><tr><td><strong>Length</strong></td><td>A 20-minute presentation, then 12 minutes of discussion that you lead, opened by the discussant</td></tr><tr><td><strong>Graded as</strong></td><td>Presentation 4% (100-point rubric) · discussant 1% (10 points) (<a href="#rubric">rubrics</a>)</td></tr><tr><td><strong>AI use</strong></td><td>🟢 AI on for preparing slides and figures (say so on your last slide); 🔴 AI off for discussant questions and posted class questions; you present and answer live</td></tr></tbody></table><h2 id="the-papers" tabindex="-1">The papers <a class="header-anchor" href="#the-papers" aria-label="Permalink to &quot;The papers&quot;">​</a></h2><p>Choose from the course&#39;s graduate seminar set: 19 papers, plus two alternates, each suited to a 20-minute presentation (the same set as the reading list&#39;s <a href="./../resources/reading-list.html#graduate-seminar-set">graduate seminar set</a>). &quot;Fits&quot; is the week whose topic the paper belongs to, with alternatives after &quot;or&quot;; the presentation goes in one of those weeks so the paper joins that week&#39;s discussion. Weeks 3, 5, 11 and 13 have few natural fits, so papers move there to balance the schedule.</p><table tabindex="0"><thead><tr><th>Paper</th><th>Fits</th><th>Why it&#39;s worth 20 minutes</th></tr></thead><tbody><tr><td>Kwa et al., &quot;Measuring AI Ability to Complete Long Software Tasks&quot; (<a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">arXiv 2503.14499</a>)</td><td>3 (the first slot) or 13</td><td>The 50% time horizon and its doubling rate: what it means for how much you can delegate at once</td></tr><tr><td>Beurer-Kellner et al., &quot;Design Patterns for Securing LLM Agents against Prompt Injections&quot; (<a href="https://arxiv.org/abs/2506.08837" target="_blank" rel="noreferrer">arXiv 2506.08837</a>)</td><td>4, or 3 or 11</td><td>Six patterns with provable resistance, and what each one costs in utility</td></tr><tr><td>Liu et al., &quot;&#39;Your AI, My Shell&#39;: Demystifying Prompt Injection Attacks on Agentic AI Coding Editors&quot; (<a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">arXiv 2509.22040</a>)</td><td>4</td><td>314 payloads planted in project files made coding editors run malicious commands up to 84% of the time</td></tr><tr><td>Debenedetti et al., &quot;Defeating Prompt Injections by Design&quot; (CaMeL) (<a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">arXiv 2503.18813</a>)</td><td>4 or 11</td><td>A privileged planner, a quarantined parser and data-flow policies: 77% of tasks solved with provable security, against 84% undefended</td></tr><tr><td>Maaz et al., &quot;Agentic Property-Based Testing: Finding Bugs Across the Python Ecosystem&quot; (<a href="https://arxiv.org/abs/2510.09907" target="_blank" rel="noreferrer">arXiv 2510.09907</a>)</td><td>6</td><td>An agent driven by one Markdown prompt wrote property tests for 100 packages; 56% of its bug reports were valid</td></tr><tr><td>Foster et al., &quot;Mutation-Guided LLM-based Test Generation at Meta&quot; (<a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">arXiv 2501.12862</a>)</td><td>7</td><td>Mutants that represent a concern, then tests to kill them, at industrial scale; 73% of tests accepted</td></tr><tr><td>Zhao, Zhou and Cohen, &quot;Do Coverage and Mutation Scores of LLM-Generated Test Suites Correlate with Their Effectiveness?&quot; (<a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">arXiv 2607.22880</a>)</td><td>7</td><td>A replication whose results diverge from the classic studies: both measures mislead when the code may already be buggy</td></tr><tr><td>Borg et al., &quot;Echoes of AI: Investigating the Downstream Effects of AI Assistants on Software Maintainability&quot; (<a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">arXiv 2507.00788</a>)</td><td>8</td><td>A preregistered two-phase study: AI sped up the first developers, with no difference for those who later evolved the code</td></tr><tr><td>He et al., &quot;Does AI-Assisted Coding Deliver? A Difference-in-Differences Study of Cursor&#39;s Impact on Software Projects&quot; (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">arXiv 2511.04427</a>)</td><td>8</td><td>Output rose and faded while warnings and complexity stayed up; note the complexity figure that differs between the text and a table</td></tr><tr><td>Cihan et al., &quot;Automated Code Review In Practice&quot; (<a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">arXiv 2412.18531</a>)</td><td>9</td><td>73.8% of AI review comments resolved, but average PR closure time rose 42%</td></tr><tr><td>Tantithamthavorn et al., &quot;RovoDev Code Reviewer: A Large-Scale Online Evaluation of LLM-based Code Review Automation at Atlassian&quot; (<a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">arXiv 2601.01129</a>)</td><td>9</td><td>A year of AI review at scale with the opposite cycle-time result: present it against Cihan et al.</td></tr><tr><td>Vero et al., &quot;BaxBench: Can LLMs Generate Correct and Secure Backends?&quot; (<a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">arXiv 2502.11844</a>)</td><td>10</td><td>Functional tests plus end-to-end exploits: about half of the correct programs were exploitable</td></tr><tr><td>Shankar et al., &quot;Who Validates the Validators? Aligning LLM-Assisted Evaluation of LLM Outputs with Human Preferences&quot; (<a href="https://arxiv.org/abs/2404.12272" target="_blank" rel="noreferrer">arXiv 2404.12272</a>)</td><td>12 or 11</td><td>Criteria drift: grading outputs changes your criteria, so don&#39;t fix a rubric before you&#39;ve looked at data</td></tr><tr><td>Wang, Pradel and Liu, &quot;Are &#39;Solved Issues&#39; in SWE-bench Really Solved Correctly?&quot; (<a href="https://arxiv.org/abs/2503.15223" target="_blank" rel="noreferrer">arXiv 2503.15223</a>)</td><td>12</td><td>29.6% of plausible patches behave differently from the ground truth; resolve rates inflated by 6.2 points</td></tr><tr><td>Liang, Garg and Zilouchian Moghaddam, &quot;The SWE-Bench Illusion: When State-of-the-Art LLMs Remember Instead of Reason&quot; (<a href="https://arxiv.org/abs/2506.12286" target="_blank" rel="noreferrer">arXiv 2506.12286</a>)</td><td>12</td><td>Models name the buggy file from the issue text alone far more often on SWE-bench than elsewhere</td></tr><tr><td>Zhu et al., &quot;Establishing Best Practices for Building Rigorous Agentic Benchmarks&quot; (<a href="https://arxiv.org/abs/2507.02825" target="_blank" rel="noreferrer">arXiv 2507.02825</a>)</td><td>12</td><td>A checklist showing task and reward flaws can distort scores by up to 100% in relative terms</td></tr><tr><td>Cui et al., &quot;The Effects of Generative AI on High-Skilled Work: Evidence from Three Field Experiments with Software Developers&quot; (<a href="https://pubsonline.informs.org/doi/fpi/10.1287/mnsc.2025.00535" target="_blank" rel="noreferrer">Management Science</a>)</td><td>14</td><td>Randomized rollouts at three firms: 26% more completed tasks, more for juniors, and no measure of quality</td></tr><tr><td>Lee et al., &quot;The Impact of Generative AI on Critical Thinking&quot; (<a href="https://advait.org/files/lee_2025_ai_critical_thinking_survey.pdf" target="_blank" rel="noreferrer">CHI 2025</a>)</td><td>14</td><td>Higher confidence in the AI predicted less critical thinking; effort shifted to verifying and integrating</td></tr><tr><td>Xu et al., &quot;LiCoEval: Evaluating LLMs on License Compliance in Code Generation&quot; (<a href="https://arxiv.org/abs/2408.02487" target="_blank" rel="noreferrer">arXiv 2408.02487</a>)</td><td>14 or 10</td><td>Near-copies of existing open-source code, and inaccurate license information, especially for copyleft</td></tr><tr><td><em>Alternate:</em> Becker et al., the METR randomized trial of experienced open-source developers (<a href="https://arxiv.org/abs/2507.09089" target="_blank" rel="noreferrer">arXiv 2507.09089</a>)</td><td>14</td><td>Developers were slower with AI tools while believing they were faster</td></tr><tr><td><em>Alternate:</em> Shen and Tamkin, a randomized trial of skill formation with AI assistance (<a href="https://arxiv.org/abs/2601.20245" target="_blank" rel="noreferrer">arXiv 2601.20245</a>)</td><td>14</td><td>Learning a new library with AI help lowered quiz scores afterward</td></tr></tbody></table><p>To present a paper that isn&#39;t on the list, propose it to the instructor by the end of week 1, with the week it fits and why it&#39;s worth 20 minutes.</p><h2 id="schedule-rules" tabindex="-1">Schedule rules <a class="header-anchor" href="#schedule-rules" aria-label="Permalink to &quot;Schedule rules&quot;">​</a></h2><ul><li><strong>Week 1:</strong> rank three papers on Canvas. <strong>End of week 2:</strong> the instructor posts the schedule of presenters and discussants.</li><li><strong>One presentation per Seminar</strong>, from week 3 to week 14, in the week the paper fits. If two students want the same week, the second moves to the paper&#39;s alternative week or a neighboring one.</li><li><strong>More graduate students than Seminars?</strong> Two 15-minute presentations on paired papers share a Seminar, or students present in pairs with a longer value-added part; the instructor decides in week 2.</li><li><strong>Swaps</strong> between two students are fine with two weeks&#39; notice to the instructor.</li><li><strong>Discussant pairings</strong> never put you as discussant in the same week as your own presentation.</li><li><strong>Recognized absences</strong> (Regulations M-1 and M-3) are rescheduled without penalty.</li><li><strong>Week 15</strong> holds the study talks, not paper presentations.</li></ul><h2 id="preparing-the-presentation" tabindex="-1">Preparing the presentation <a class="header-anchor" href="#preparing-the-presentation" aria-label="Permalink to &quot;Preparing the presentation&quot;">​</a></h2><p>A good 20 minutes does more than summarize. Combining CU Boulder&#39;s rubric with NC State&#39;s checklist (<a href="https://github.com/gai4se/GAI4SE-Course" target="_blank" rel="noreferrer">GAI4SE</a>):</p><ol><li><strong>The biggest takeaways first,</strong> and why the paper matters for engineers using agents now.</li><li><strong>The method, honestly:</strong> who or what was studied, what was measured and compared, and the characteristics of the data. Distinguish what the paper shows from what it claims, and tag your own claims about it observed or inferred.</li><li><strong>The results, properly:</strong> the numbers that matter, with their uncertainty, and the ones that don&#39;t add up (several papers on the list have a figure that disagrees with its own table).</li><li><strong>Value added:</strong> something the paper doesn&#39;t give the class. CU Boulder&#39;s examples are a hands-on activity or your own analysis of the tool. At $0 that could be running the paper&#39;s probe on one model on the lab machine, applying its checklist to the class codebase, or reproducing one table from released data.</li><li><strong>Discussion questions</strong> that connect it to the course: the class&#39;s own labs, the team project, the week&#39;s topic.</li></ol><p>Send the instructor a one-paragraph outline <strong>a week before</strong>, share your slides with the discussant and the instructor <strong>48 hours before</strong> the Seminar, and post them on Canvas afterward.</p><h2 id="rubric" tabindex="-1">Rubric <a class="header-anchor" href="#rubric" aria-label="Permalink to &quot;Rubric&quot;">​</a></h2><p><strong>Presentation (100 points, 4% of the course)</strong>, after CU Boulder&#39;s CSCI 7000-05 presentation rubric (<a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperPresentation.html" target="_blank" rel="noreferrer">CU Boulder</a>).</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Presentation of the content</strong> (30)</td><td><strong>27–30</strong> · The question, method, results and limitations, accurate and with numbers; separates what is shown from what is claimed; in time</td><td><strong>21–26</strong> · Accurate and complete, with one gap</td><td><strong>10–20</strong> · A summary of the abstract, or a misstated result</td><td><strong>0</strong> · Not presented</td></tr><tr><td><strong>Value added</strong> (30)</td><td><strong>27–30</strong> · A hands-on activity, a small replication, or your own analysis that the paper doesn&#39;t contain, connected to the course</td><td><strong>21–26</strong> · A clear added analysis or example</td><td><strong>10–20</strong> · Little beyond the paper</td><td><strong>0</strong> · None</td></tr><tr><td><strong>Materials</strong> (20)</td><td><strong>18–20</strong> · Slides readable at a distance, figures redrawn or explained, sources cited on the slides; shared 48 hours ahead</td><td><strong>14–17</strong> · Clear, with minor problems</td><td><strong>7–13</strong> · Dense or hard to read; late</td><td><strong>0</strong> · None</td></tr><tr><td><strong>Leading the discussion</strong> (20)</td><td><strong>18–20</strong> · Uses the discussant&#39;s questions and at least two of the class&#39;s posted questions; draws in several people; keeps time</td><td><strong>14–17</strong> · A real discussion with a few voices</td><td><strong>7–13</strong> · Mostly answering one question</td><td><strong>0</strong> · No discussion</td></tr></tbody></table><h2 id="the-discussant" tabindex="-1">The discussant <a class="header-anchor" href="#the-discussant" aria-label="Permalink to &quot;The discussant&quot;">​</a></h2><p><strong>10 points, 1% of the course.</strong> As discussant for a classmate&#39;s presentation you:</p><ol><li><strong>Read the paper</strong> before you see the slides.</li><li><strong>Prepare three questions</strong> (🔴 AI off) and send them to the presenter and the instructor <strong>48 hours before</strong> the Seminar: one about the method, one about whether the results hold up, and one about what they mean for practice or for this course.</li><li><strong>Open the discussion</strong> with one of them, in the Seminar.</li><li><strong>Submit a short note</strong> on Canvas (🔴 AI off, about 250 words) within 48 hours afterward: your three questions, what the discussion settled, and what it didn&#39;t.</li></ol><table tabindex="0"><thead><tr><th>Criterion</th><th>Full</th><th>Partial</th><th>None</th></tr></thead><tbody><tr><td><strong>Questions</strong></td><td><strong>5</strong> · Three specific questions that go beyond the abstract (method, validity, implications), on time</td><td><strong>3</strong> · Three questions, one generic or late</td><td><strong>0</strong> · Not sent</td></tr><tr><td><strong>In the Seminar</strong></td><td><strong>2</strong> · Opens the discussion and follows up</td><td><strong>1</strong> · Asks one question</td><td><strong>0</strong> · Absent without arrangement</td></tr><tr><td><strong>Note</strong></td><td><strong>3</strong> · What was settled and what wasn&#39;t, specifically</td><td><strong>2</strong> · A summary without judgment</td><td><strong>0</strong> · Missing</td></tr></tbody></table><h2 id="questions-from-the-class" tabindex="-1">Questions from the class <a class="header-anchor" href="#questions-from-the-class" aria-label="Permalink to &quot;Questions from the class&quot;">​</a></h2><p>In every week with a presentation, each student who isn&#39;t presenting or discussing, undergraduate or graduate, posts <strong>one question about the paper</strong> on the Canvas discussion by <strong>11:59 pm the night before the Seminar</strong> (🔴 AI off). Read the paper&#39;s abstract and introduction, plus at least one results section, before you write it. Cornell&#39;s CS 6158 builds its discussions the same way, from classmates&#39; posted questions (<a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/" target="_blank" rel="noreferrer">Cornell CS 6158</a>).</p><p>Posting your question by the deadline counts as taking part in that Seminar (<a href="./../assessment/rubrics.html#reading-responses-and-seminar-participation">participation rubric</a>). In a week with a presentation, the paper is usually that week&#39;s reading, so your reading response and your question can draw on the same reading.</p>',23)])])}const c=e(o,[["render",n]]);export{p as __pageData,c as default};
